/**
 * Cross-language parity: TypeScript port vs the original Python engine.
 *
 * `fixtures-python.json` is generated by running the production Python
 * `naming_service.score_name()` over 200 names — 20 hand-picked to cover every
 * structural shape (single/compound surname × single/double given name, the
 * surname-reading overrides 任/单/区/朴, with and without birth data) plus 180
 * seeded-random common names.
 *
 * Every derived value is compared exactly: the five grids and their grades, the 三才
 * configuration and grade, all four dimension scores and the total, the 八字 verdict
 * *including its generated prose*, the 生肖 per-character verdicts, the three fortunes,
 * and the 音律 analysis.
 *
 * A divergence here means the port would score a name differently than the live site.
 */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { scoreName } from '../src/index.js';

interface Fixture {
  in: {
    surname: string;
    given: string;
    xiYong: string[] | null;
    jiShen: string[] | null;
    zodiac: string | null;
  };
  grids: Record<string, number>;
  grid_levels: Record<string, string>;
  sancai: { combo: string; level: string; tian_ren: string; ren_di: string };
  scores: { shuli: number; sancai: number; bazi: number | null; zodiac: number | null; total: number };
  bazi_verdict: string | null;
  bazi_text: string | null;
  zodiac_score: number | null;
  zodiac_given_verdicts: string[] | null;
  yunshi: Array<{ name: string; level: string; combo: string; relation: string }>;
  phonetics: { level: string; note: string; tones: number[] };
  chars: Array<{ char: string; kx: number; wx: string | null; py: string | null; zhuyin: string | null }>;
}

const here = dirname(fileURLToPath(import.meta.url));
const fixtures = JSON.parse(readFileSync(join(here, 'fixtures-python.json'), 'utf8')) as Fixture[];

const mismatches: string[] = [];
let compared = 0;

function eq(label: string, a: unknown, b: unknown) {
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    mismatches.push(`${label}: TS=${JSON.stringify(a)} Python=${JSON.stringify(b)}`);
  }
}

for (const f of fixtures) {
  const name = `${f.in.surname}${f.in.given}`;
  const got = scoreName(f.in.surname, f.in.given, {
    xiYong: f.in.xiYong ?? undefined,
    jiShen: f.in.jiShen ?? undefined,
    zodiac: f.in.zodiac ?? undefined,
  });
  compared++;

  // 五格 numbers and grades
  for (const k of ['tian', 'ren', 'di', 'wai', 'zong']) {
    eq(`${name}.grids.${k}`, got.grids[k].num, f.grids[k]);
    eq(`${name}.grid_levels.${k}`, got.grids[k].level, f.grid_levels[k]);
  }

  // 三才
  eq(`${name}.sancai.combo`, got.sancai.combo, f.sancai.combo);
  eq(`${name}.sancai.level`, got.sancai.level, f.sancai.level);
  eq(`${name}.sancai.tian_ren`, got.sancai.tian_ren, f.sancai.tian_ren);
  eq(`${name}.sancai.ren_di`, got.sancai.ren_di, f.sancai.ren_di);

  // 分项得分与总分
  eq(`${name}.scores`, got.scores, f.scores);

  // 八字维度 — including the generated prose, which is where facts get folded in
  eq(`${name}.bazi_verdict`, got.bazi_match?.verdict ?? null, f.bazi_verdict);
  eq(`${name}.bazi_text`, got.bazi_match?.verdict_text ?? null, f.bazi_text);

  // 生肖维度
  eq(`${name}.zodiac_score`, got.zodiac_match?.score ?? null, f.zodiac_score);
  eq(
    `${name}.zodiac_verdicts`,
    got.zodiac_match?.given.map((d) => d.verdict) ?? null,
    f.zodiac_given_verdicts,
  );

  // 三条运势
  eq(
    `${name}.yunshi`,
    got.yunshi.map((y) => ({ name: y.name, level: y.level, combo: y.combo, relation: y.relation })),
    f.yunshi,
  );

  // 音律 — note included: the surname-reading override feeds the tone analysis
  eq(`${name}.phonetics.level`, got.phonetics.level, f.phonetics.level);
  eq(`${name}.phonetics.note`, got.phonetics.note, f.phonetics.note);
  eq(`${name}.phonetics.tones`, got.phonetics.tones.map((t) => t.tone), f.phonetics.tones);

  // 逐字
  eq(
    `${name}.chars`,
    got.chars.map((c) => ({ char: c.char, kx: c.kx, wx: c.wx, py: c.py, zhuyin: c.zhuyin })),
    f.chars,
  );
}

if (mismatches.length) {
  console.error(`\n${mismatches.length} mismatches across ${compared} names:`);
  for (const m of mismatches.slice(0, 40)) console.error('  ✗ ' + m);
  if (mismatches.length > 40) console.error(`  … and ${mismatches.length - 40} more`);
  process.exit(1);
}

assert.equal(compared, fixtures.length);
console.log(`✓ parity: ${compared} names — grids, 三才, scores, 八字 prose, 生肖, 运势, 音律 all identical to the Python engine.`);
